    "m82b7cf40b5e6": "Текущий статус",
    "m4f16392768a7": "Подтверждаю: слова-подсказки, параметры, материалы и результаты будут обнародованы, а также последующие успешно сохраненные модификации. Пожалуйста, сначала проверьте, содержит ли контент секреты; только чтение не предотвращает копирование, а закрытие или сброс ссылки не может восстановить полученный контент и копии.",
